import React, { useEffect, useState } from "react";

import useApi from "../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import entitiesApi from "../../../api/entitiesApi";
import { getLoggedInUser } from "../../../helpers/authUtils";
import VisitorsFormModal from "./VisitorsFormModal";
import VisitorsCheckoutFormModal from "./VisitorsCheckoutFormModal";
import { Loading } from "../../../components";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import VisitorsTable from "./AllVisitorsTable";

const columns = [
  { name: "Names", uid: "visitor_names" },
  { name: "Phone", uid: "visitort_phone" },
  { name: "Country", uid: "country_title" },
  { name: "Department Visited", uid: "department_title" },
  { name: "Arrival", uid: "arrival_time" },
  { name: "Departure", uid: "departure_time" },
  { name: "Status", uid: "status" },
  { name: "Actions", uid: "actions" },
];

function VisitorsList() {
  const [openVisitorFormModal, setopenVisitorFormModal] = useState(false);

  const navigate = useNavigate();
  const [visitorTicket, setVisitorTicket] = useState();
  const [visitorTickets, setVisitorTickets] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const visitorTicketsActionsApi = useApi(hospitalsApi.hospitalsOpenAction);
  const [openVisitorCheckoutModal, setopenVisitorCheckoutModal] =
    useState(false);

  const [user, setUser] = useState();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  const getVisitorTickets = async () => {
    setVisitorTickets([]);
    await visitorTicketsActionsApi.request({
      action: "GetAllVisitorTickets",
    });
  };

  useEffect(() => {
    getVisitorTickets();
  }, []);

  useEffect(() => {
    if(updated){
       getVisitorTickets();
    }
   
  }, [updated]);

  const handleEditAction = (item) => {
    setopenVisitorCheckoutModal(true);

    setUpdated(false);

    setVisitorTicket(item);
    setmodalTitle(`${item.visitor_names}`);
  };

  const handleAddAction = () => {
    if (user && user.is_staff === "True") {
      setopenVisitorFormModal(true);
    } else {
      setopenVisitorFormModal(true);
    }
    setUpdated(false);

    setmodalTitle("Add new visitor ticket");
    setVisitorTicket(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/entities/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/entities/delete/${item.id}`);
  };

  useEffect(() => {
    if (visitorTicketsActionsApi.data && visitorTicketsActionsApi.data.length) {
      setVisitorTickets(visitorTicketsActionsApi.data);
    }

    console.log("entitiesActionsApi.data", visitorTicketsActionsApi.data);
  }, [visitorTicketsActionsApi.data]);

  useEffect(() => {
    if (updated === true) {
      getVisitorTickets();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(visitorTickets);
  }, [visitorTickets]);

  const handleFilter = (e) => {
    console.log("eeeee", e);
    const search_param = e;

    if (search_param && search_param !== null) {
      setdata(
        visitorTickets.filter((x) =>
          x.visitor_names.toLowerCase().includes(search_param)||x.visitor_phone.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(visitorTicketsActionsApi.data);
    }

  };

  return (
    <div className="mt-16 md:mt-0">
      {openVisitorFormModal && (
        <VisitorsFormModal
          openEditModal={openVisitorFormModal}
          setopenEditModal={setopenVisitorFormModal}
          item={visitorTicket}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      {openVisitorFormModal && (
        <VisitorsFormModal
          openEditModal={openVisitorFormModal}
          setopenEditModal={setopenVisitorFormModal}
          visitorTicket={visitorTicket}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      {openVisitorCheckoutModal && (
        <VisitorsCheckoutFormModal
          openCheckoutModal={openVisitorCheckoutModal}
          setopenCheckoutModal={setopenVisitorCheckoutModal}
          visitorTicket={visitorTicket}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      {visitorTicketsActionsApi.loading ? (
        <Loading loading={visitorTicketsActionsApi.loading} />
      ) : (
        <VisitorsTable
          data={data}
          columns={columns}
          editAction={handleEditAction}
          detailsAction={handleDetailsAction}
          deleteAction={handleDeleteAction}
          addAction={handleAddAction}
          handleFilter={handleFilter}
        />
      )}
    </div>
  );
}

export default VisitorsList;
