import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomTimePicker,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";

import { Modal } from "antd";

import dayjs from "dayjs";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";

export default function VisitorsCheckoutFormModal({
  openCheckoutModal,
  setopenCheckoutModal,
  visitorTicket,
  modalTitle = "Create visitor ticket",
  updated,
  setUpdated,
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();

  const { currentColor } = useStateContext();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  const [errors, setErrors] = useState();

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const updateVisitorTicketApi = useApi(hospitalsApi.hospitalsOpenAction);

  const updateVisitorTicket = async (data) => {
    await updateVisitorTicketApi.request(data);
  };

  useEffect(() => {
    console.log("updateVisitorTicketApi.data", updateVisitorTicketApi.data);
    if (
      updateVisitorTicketApi.data &&
      updateVisitorTicketApi.data.visitor_ticket
    ) {
      setUpdated(true);
      setopenCheckoutModal(false);
    }

    if (
      updateVisitorTicketApi.data &&
      updateVisitorTicketApi.data.errors &&
      updateVisitorTicketApi.data.errors.length
    ) {
      setErrors(updateVisitorTicketApi.data.errors);
    }
  }, [updateVisitorTicketApi.data]);
  const formik = useFormik({
    initialValues: {
      departure_time: "",
    },

    validationSchema: Yup.object({
      departure_time: Yup.string().required("Departure time is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      const data = {
        action: "UpdateVisitorTicket",
        visitor_ticket: visitorTicket.id,
        departure_time: values.departure_time,
      };

      updateVisitorTicket(data);

      resetForm();
    },
  });

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setopenCheckoutModal(false);
  };
  const handleCancel = () => {
    setopenCheckoutModal(false);
  };

  const handleSelectCheckoutTime = (time, timeString) => {
    formik.setFieldValue(
      "departure_time",
      dayjs(time).format("YYYY-MM-DD HH:mm")
    );
  };

  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={
          visitorTicket ? `Checkout ${visitorTicket.visitor_names}` : modalTitle
        }
        open={openCheckoutModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            touched={formik.touched.departure_time}
            error={formik.errors.departure_time}
          >
            <CustomTimePicker
              id="departure_time"
              name="departure_time"
              onChange={handleSelectCheckoutTime}
              placeholder="Select checkout time"
              size="large"
              label="Select checkout time"
              value={formik.values.departure_time}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
